// Generar respuesta con información general del taller
const inputData = $input.first().json;
const mensaje = (inputData.mensaje || '').toLowerCase();
const telefono = inputData.telefono || '';
const nombre = inputData.nombre || '';

let respuesta = '¡Hola ' + (nombre || '') + '! 😊\n\n';

// Detectar tipo de información solicitada
if (/horario|hora|abren|cierran|abierto|abrimos/i.test(mensaje)) {
  respuesta += '🕐 *Horarios de Atención:*\n\n'
    + 'Lunes a Viernes: 9:00 AM - 6:00 PM\n'
    + 'Sábados: 9:00 AM - 2:00 PM\n'
    + 'Domingos: Cerrado\n\n'
    + '¡Estamos listos para atenderte! 🛵';
} else if (/direccion|dirección|ubicación|ubicacion|dónde están|donde estan|calle|cómo llegar|mapa/i.test(mensaje)) {
  respuesta += '📍 *Ubicación:*\n\n'
    + 'Calle Principal #123, Col. Centro\n'
    + 'C.P. 80000, Culiacán, Sinaloa\n\n'
    + 'Estamos a una cuadra del parque central, frente a la farmacia. ¡Fácil de encontrar! 🗺️';
} else if (/pago|pagar|tarjeta|efectivo|transferencia|crédito|débito|formas de pago/i.test(mensaje)) {
  respuesta += '💳 *Formas de Pago:*\n\n'
    + '✅ Efectivo\n'
    + '✅ Tarjeta de débito\n'
    + '✅ Tarjeta de crédito (Visa, Mastercard)\n'
    + '✅ Transferencia bancaria\n'
    + '✅ Mercado Pago\n\n'
    + 'Aceptamos todas las formas de pago para tu comodidad. 😊';
} else if (/tiempo|demora|tarda|entrega|lleva|listo/i.test(mensaje)) {
  respuesta += '⏱️ *Tiempos de Servicio:*\n\n'
    + '🔧 *Cambio de aceite:* 30 min\n'
    + '🔧 *Frenos:* 1-2 hrs\n'
    + '🔧 *Afinación:* 2-3 hrs\n'
    + '🔧 *Suspensión:* 2-4 hrs\n'
    + '🔧 *Revisión general:* 30 min\n'
    + '🔧 *Diagnóstico completo:* 1 hr\n\n'
    + 'Los tiempos pueden variar según la carga de trabajo del taller. ¡Te avisamos cuando esté lista! 🛵';
} else if (/servicio|ofrecen|hacen|reparación|reparacion|mantenimiento/i.test(mensaje)) {
  respuesta += '🔧 *Servicios que Ofrecemos:*\n\n'
    + '✅ Cambio de aceite y filtros\n'
    + '✅ Frenos (balatas, líquido, rectificación)\n'
    + '✅ Afinación general\n'
    + '✅ Suspensión (horquillas, amortiguadores)\n'
    + '✅ Sistema eléctrico (luces, batería, arranque)\n'
    + '✅ Carburación e inyección electrónica\n'
    + '✅ Transmisión (cadena, catalina, piñón)\n'
    + '✅ Llantas (venta y montaje)\n'
    + '✅ Diagnóstico computarizado\n'
    + '✅ Reparación de escapes\n'
    + '✅ Servicio completo de pintura\n\n'
    + '¿Qué servicio necesitas? Con gusto te damos más detalles. 😊';
} else {
  // Respuesta general con toda la información
  respuesta += 'Bienvenido a *Moto Servicios TIMON* 🛵🔧\n\n'
    + 'Somos tu taller de confianza para el mantenimiento y reparación de motocicletas.\n\n'
    + '📍 *Ubicación:* Calle Principal #123, Col. Centro\n'
    + '🕐 *Horario:* Lun-Sáb 9:00 AM - 6:00 PM (Sáb hasta 2PM)\n'
    + '📞 *Teléfono:* 123-456-7890\n'
    + '💳 *Pago:* Efectivo, tarjeta, transferencia\n\n'
    + '¿En qué podemos ayudarte? Pregunta por servicios, precios, horarios o lo que necesites. 😊';
}

return [
  {
    json: {
      telefono: telefono,
      mensaje: inputData.mensaje || '',
      respuesta: respuesta,
      categoria: 'INFORMACION'
    }
  }
];
